# T-shapes: bar of 3 perpendicular with stem of 2? Example: rows1-2: cell(1,3) and (2,2),(2,3),(2,4): center (2,3), stem up 1. So stem length 1 here.
def find_ts(g):
    g=np.array(g); H,W=g.shape; res=[]
    for r in range(H):
        for c in range(W):
            if g[r,c]==2:
                for dr,dc,d in [(-1,0,'up'),(1,0,'down'),(0,-1,'left'),(0,1,'right')]:
                    s1=(r+dr,c+dc)
                    if 0<=s1[0]<H and 0<=s1[1]<W and g[s1]==2:
                        # bar perpendicular
                        per=[(-dc,-dr),(dc,dr)] if d in('up','down') else [(-dr,-dc),(dr,dc)]
                        b1=(r+per[0][0],c+per[0][1]); b2=(r+per[1][0],c+per[1][1])
                        if all(0<=x<H and 0<=y<W and g[x,y]==2 for x,y in [b1,b2]):
                            res.append((r,c,d))
    return res
