from collections import deque
def comps(g):
    g=np.array(g); H,W=g.shape; seen=np.zeros_like(g,bool); out=[]
    for r in range(H):
        for c in range(W):
            if g[r,c]==2 and not seen[r,c]:
                q=deque([(r,c)]); seen[r,c]=1; cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a,b]==2 and not seen[a,b]:
                            seen[a,b]=1; q.append((a,b))
                out.append(sorted(cells))
    return out
