        for c in range(W):
            if g[r,c]==2:
                for dr,dc in [(-1,0),(1,0)]:
                    if 0<=r+dr<H and g[r+dr,c+dr*0]==2:
                        b1=(r-dc,c-dr); b2=(r+dc,c+dr)
                        if all(0<=x<H and 0<=y<W and g[x,y]==2 for x,y in [b1,b2]):
                            ts.append((r,c,'up' if dr<0 else 'down'))
